  const {
  name, count, mode, show, items, label, value, custom,
  settings, context, locales, amount, date
} = props;
  return (<section>{show ? <Subject branch={mode} summary="One" details="Many">Fallback</Subject> : <aside>Empty {name}</aside>}</section>);
}

